        if self.added:
            val = heapq.heappop(self.added)
            self.added_set.remove(val)
            return val
        val = self.cur
        self.cur += 1
        return val

    def addBack(self, num: int) -> None:
        if num < self.cur and num not in self.added_set:
            heapq.heappush(self.added, num)
            self.added_set.add(num)

class SmallestInfiniteSet {
private:
    int cur;
    std::set<int> added;
public:
    SmallestInfiniteSet() : cur(1) {}

    int popSmallest() {
        if (!added.empty()) {
            int val = *added.begin();
            added.erase(added.begin());
            return val;
        }
        return cur++;
    }

    void addBack(int num) {
        if (num < cur) {
            added.insert(num);
        }
    }
};

class SmallestInfiniteSet {
    private int cur;
    private java.util.TreeSet<Integer> added;
    public SmallestInfiniteSet() {
        cur = 1;
        added = new java.util.TreeSet<>();
    }
    public int popSmallest() {
        if (!added.isEmpty()) {
            int val = added.first();
            added.remove(val);
            return val;
        }
        return cur++;
    }
    public void addBack(int num) {
        if (num < cur) {
            added.add(num);
        }
    }
}

var SmallestInfiniteSet = function() {
    this.cur = 1;
    this.added = new Set();
};

SmallestInfiniteSet.prototype.popSmallest = function() {
    if (this.added.size > 0) {
        let minVal = Infinity;
        for (const v of this.added) {
            if (v < minVal) minVal = v;
        }
        this.added.delete(minVal);
        return minVal;
    }
    return this.cur++;
};

SmallestInfiniteSet.prototype.addBack = function(num) {
    if (num < this.cur) {
        this.added.add(num);
    }
};
